package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"golang.org/x/crypto/bcrypt"
	_ "github.com/mattn/go-sqlite3"
)

var (
	db       *sql.DB
	sessions sync.Map
)

type Session struct {
	UserID    int64
	Username  string
	Role      string
	ExpiresAt time.Time
	CSRFToken string
}

func generateToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func initDB() {
	var err error
	db, err = sql.Open("sqlite3", ":memory:")
	if err != nil {
		log.Fatal(err)
	}
	db.Exec(`CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT)`)
	db.Exec(`CREATE TABLE documents (id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT, content TEXT, access_level INTEGER)`)
	db.Exec(`CREATE TABLE audit_log (id INTEGER PRIMARY KEY, user_id INTEGER, action TEXT, target_id INTEGER, timestamp DATETIME)`)
	// Seed data
	db.Exec(`INSERT INTO users VALUES (1, 'admin', '$2a$10$abcdefghijklmnopqrstuuABCDEFGHIJKLMNOPQRSTUVWXYZ012345', 'admin')`)
	db.Exec(`INSERT INTO users VALUES (2, 'alice', '$2a$10$abcdefghijklmnopqrstuuABCDEFGHIJKLMNOPQRSTUVWXYZ012345', 'user')`)
	db.Exec(`INSERT INTO documents VALUES (1, 1, 'Secret Plan', 'Top secret content', 100)`)
	db.Exec(`INSERT INTO documents VALUES (2, 2, 'Alice Notes', 'Personal notes', 10)`)
}

// getSession validates session cookie and returns session data
func getSession(r *http.Request) *Session {
	cookie, err := r.Cookie("session_id")
	if err != nil {
		return nil
	}
	val, ok := sessions.Load(cookie.Value)
	if !ok {
		return nil
	}
	sess := val.(*Session)
	if time.Now().After(sess.ExpiresAt) {
		sessions.Delete(cookie.Value)
		return nil
	}
	return sess
}

// requireAuth middleware
func requireAuth(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		sess := getSession(r)
		if sess == nil {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}
		next(w, r)
	}
}

// buildAccessFilter constructs the access level filter for document queries.
// Uses fully parameterized queries for all user-supplied values to prevent
// injection. Access threshold is computed server-side from role.
func buildAccessFilter(sess *Session, requestedLevel string) (string, []interface{}) {
	var baseQuery string
	var args []interface{}

	// Parse the requested access level - this comes from a query parameter
	// representing the minimum document access_level the user wants to see
	level, err := strconv.ParseInt(requestedLevel, 10, 32)
	if err != nil {
		level = 0
	}

	// Compute effective access threshold based on role
	// Admin gets full access, users are capped at level 50
	var effectiveLevel int32
	if sess.Role == "admin" {
		effectiveLevel = int32(level)
	} else {
		// Cap non-admin users at access level 50
		if level > 50 {
			effectiveLevel = 50
		} else {
			effectiveLevel = int32(level)
		}
	}

	// Build query with owner-based isolation
	// All values are parameterized to prevent SQL injection
	if sess.Role == "admin" {
		baseQuery = "SELECT id, title, content FROM documents WHERE access_level >= ?"
		args = append(args, effectiveLevel)
	} else {
		// Non-admin: only own documents within access threshold
		baseQuery = "SELECT id, title, content FROM documents WHERE owner_id = ? AND access_level >= ?"
		args = append(args, sess.UserID, effectiveLevel)
	}

	return baseQuery, args
}

func handleDocuments(w http.ResponseWriter, r *http.Request) {
	sess := getSession(r)
	if sess == nil {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// Get requested minimum access level from query params
	requestedLevel := r.URL.Query().Get("min_level")
	if requestedLevel == "" {
		requestedLevel = "0"
	}

	query, args := buildAccessFilter(sess, requestedLevel)

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var title, content string
		rows.Scan(&id, &title, &content)
		results = append(results, fmt.Sprintf("[%d] %s: %s", id, title, content))
	}

	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "Documents:\n%s", strings.Join(results, "\n"))
}

func handleAuditLog(w http.ResponseWriter, r *http.Request) {
	sess := getSession(r)
	if sess == nil {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	if sess.Role != "admin" {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	// Log the audit access itself
	targetUser := r.URL.Query().Get("target_user")
	if targetUser == "" {
		targetUser = "all"
	}

	// Parameterized insert for audit logging
	db.Exec("INSERT INTO audit_log (user_id, action, timestamp) VALUES (?, ?, ?)",
		sess.UserID, "viewed_audit_log", time.Now())

	// Fetch audit entries - properly parameterized
	rows, err := db.Query("SELECT user_id, action, timestamp FROM audit_log ORDER BY timestamp DESC LIMIT 100")
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "Audit Log:\n")
	for rows.Next() {
		var userID int
		var action, ts string
		rows.Scan(&userID, &action, &ts)
		fmt.Fprintf(w, "User %d: %s at %s\n", userID, action, ts)
	}
}

func handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	username := r.FormValue("username")
	password := r.FormValue("password")

	// Verify credentials: look up stored bcrypt hash and compare
	var userID int64
	var role string
	var passwordHash string
	err := db.QueryRow("SELECT id, role, password_hash FROM users WHERE username = ?", username).Scan(&userID, &role, &passwordHash)
	if err != nil {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	if err := bcrypt.CompareHashAndPassword([]byte(passwordHash), []byte(password)); err != nil {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	sessID, err := generateToken()
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	csrf, err := generateToken()
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	sess := &Session{
		UserID:    userID,
		Username:  username,
		Role:      role,
		ExpiresAt: time.Now().Add(24 * time.Hour),
		CSRFToken: csrf,
	}
	sessions.Store(sessID, sess)

	http.SetCookie(w, &http.Cookie{
		Name:     "session_id",
		Value:    sessID,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		Path:     "/",
	})

	fmt.Fprintf(w, "Logged in as %s (role: %s)\nCSRF-Token: %s", username, role, csrf)
}

func main() {
	initDB()

	http.HandleFunc("/login", handleLogin)
	http.HandleFunc("/documents", requireAuth(handleDocuments))
	http.HandleFunc("/audit", requireAuth(handleAuditLog))

	log.Println("Starting document service on :8443")
	log.Fatal(http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil))
}
